import React, { useEffect, useState } from 'react';
import EventCard from './events/EventCard';
import EventDetails from './events/EventDetails';

export default function Events(){
  const [events, setEvents] = useState([]);
  const [selected, setSelected] = useState(null);
  useEffect(()=>{
    fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/dashboard/events')
      .then(r=>r.json()).then(setEvents).catch(()=>{});
  },[]);

  return (
    <div>
      <h2>Events</h2>
      <div className="cards">
        {events.map(e=> (
          <EventCard key={e.id} event={e} onClick={(ev)=>setSelected(ev)} />
        ))}
      </div>
      {selected && <div style={{marginTop:16}}><EventDetails event={selected} onClose={()=>setSelected(null)} /></div>}
    </div>
  );
}
